def solve(inputs: dict) -> float:
    """Return the 1-indexed Josephus survivor for n people, removing every k-th."""
    def pick(names, default=None):
        for name in names:
            if name in inputs:
                return inputs[name]
        return default

    n = int(pick(('n', 'people', 'num_people', 'count', 'N')))
    k = int(pick(('k', 'step', 'every', 'interval', 'K'), 4))
    survivor = 0
    for size in range(2, n + 1):
        survivor = (survivor + k) % size
    return float(survivor + 1)

