def solve(inputs: dict) -> float:
    """Compute base**exponent modulo modulus."""
    def get(*names):
        for name in names:
            if name in inputs:
                return inputs[name]
        raise KeyError(names[0])
    base = int(get('base', 'a', 'number', 'value'))
    exponent = int(get('exponent', 'exp', 'power', 'e'))
    modulus = int(get('modulus', 'mod', 'm'))
    return float(pow(base, exponent, modulus))

